"""Remove All Adjacent Duplicates In String — stack.

Time: O(n)   Space: O(n)
"""


class Solution:
    def removeDuplicates(self, s: str) -> str:
        stack = []
        for ch in s:
            if stack and stack[-1] == ch:
                stack.pop()
            else:
                stack.append(ch)
        return "".join(stack)
